\"country\",[\"^ \",\"^W\",[\"^ \",\"weight\",-1],\"^J\",[\"^ \",\"^5K\",-1],\"^G\",[\"^ \",\"^5K\",-2],\"^=\",false,\"^L\",[\"^ \",\"^5K\",-1]],\"indicator\",[\"^ \",\"^1P\",[\"^ \",\"^5K\",-1],\"^18\",[\"^ \",\"^5K\",-1]]],\"banner\",[\"^ \",\"^4\",false],\"en_TopicPortalData\",[\"^ \",\"3\",[\"^ \",\"^7\",\"Economy & Growth\",\"portals\",[[\"^ \",\"descriptionHtml\",\"The <a href='http://datatopics.worldbank.org/consumption/'>Global Consumption Database</a> is a one-stop source of data on household consumption patterns in developing countries. It is designed to serve a wide range of users - from researchers seeking data for analytical studies to businesses seeking a better understanding of the markets into which they are expanding or those they are already serving.\",\"href\",\"http://datatopics.worldbank.org/consumption/\",\"img\",\"/media/portal-images/Portal-Global-Consumption-Database.jpg\",\"^7\",\"Household Consumption Data and Statistics\"]]],\"4\",[\"^ \",\"^7\",\"Education\",\"^5M\",[[\"^ \",\"^5N\",\"The <a href='http://datatopics.worldbank.org/education'>World Bank EdStats</a> (Education Statistics) portal is your comprehensive data and analysis source for key topics in education. EdStats tools, resources and queries help users visualize and analyze education data.\",\"^5O\",\"http://datatopics.worldbank.org/education\",\"img\",\"/media/portal-images/Portal-EdStats.png\",\"^7\",\"Education Statistics: EdStats\"],[\"^ \",\"^5N\",\"<a href='http://datatopics.worldbank.org/sdi'> Service Delivery Indicators </a> is a Africa wide initiative that collects actionable data on service delivery in schools and health facilities to assess quality and performance, track progress, and empower citizens to hold governments accountable for public spending.\",\"^5O\",\"http://datatopics.worldbank.org/sdi\",\"img\",\"/media/portal-images/Portal-Service-Delivery-Indicators.jpg\",\"^7\",\"Service Delivery Indicators\"]]],\"5\",[\"^ \",\"^7\",\"Energy & Mining\",\"^5M\",[[\"^ \",\"^5N\",\"The <a href='https://energydata.info'>Energy &amp; Extractives Open Data Platform </a> is provided by the World Bank Group and is comprised of open datasets relating to the work of the Energy &amp; Extractives Global Practice, including statistical, measurement and survey data from ongoing projects.\",\"^5O\",\"https://energydata.info\",\"img\",\"/media/portal-images/Portal-EE-OpenData.png\",\"^7\",\"Energy & Extractives Open Data Platform\"]]],\"7\",[\"^ \",\"^7\",\"Financial Sector\",\"^5M\",[[\"^ \",\"^5N\",\"The <a href='http://datatopics.worldbank.org/g20fidata'>G20 Financial Inclusion Indicators</a> were developed by the Global Partnership for Financial Inclusion (GPFI) and were endorsed by G20 Leaders at their St. Petersburg Summit in September 2013.\",\"^5O\",\"http://datatopics.worldbank.org/g20fidata\",\"img\",\"/media/portal-images/Portal-G20-Financial-Inclusion-Indicators.jpg\",\"^7\",\"Financial Inclusion\"]]],\"8\",[\"^ \",\"^7\",\"Health\",\"^5M\",[[\"^ \",\"^5N\",\"<a href='http://datatopics.worldbank.org/hnp'>HealthStats</a> is the World Bank\\\"s comprehensive database of Health, Nutrition and Population (HNP) statistics.\",\"^5O\",\"http://datatopics.worldbank.org/hnp\",\"img\",\"/media/portal-images/Portal-HNP.png\",\"^7\",\"HealthStats\"],[\"^ \",\"^5N\",\"<a href='http://datatopics.worldbank.org/sdi'>Service Delivery Indicators</a> is a Africa wide initiative that collects actionable data on service delivery in schools and health facilities to assess quality and performance, track progress, and empower citizens to hold governments accountable for public spending.\",\"^5O\",\"http://datatopics.worldbank.org/sdi\",\"img\",\"/media/portal-images/Portal-Service-Delivery-Indicators.jpg\",\"^7\",\"Service Delivery Indicators\"]]],\"10\",[\"^ \",\"^7\",\"Social Protection & Labor\",\"^5M\",[[\"^ \",\"^5N\",\"<a href='http://datatopics.worldbank.org/aspire'>ASPIRE</a> is an ongoing project to compile comprehensive and harmonized data on Social Protection and Labor (SPL) programs and systems.\",\"^5O\",\"https://www.worldbank.org/en/data/datatopics/aspire\",\"img\",\"/media/portal-images/Portal-ASPIRE.jpg\",\"^7\",\"ASPIRE: The Atlas of Social Protection\"],[\"^ \",\"^5N\",\"<p>Access regional and country dashboards displaying tables and graphs with the latest data and trends on Jobs.</p>\",\"^5O\",\"https://datatopics.worldbank.org/jobsdiagnostics/\",\"img\",\"/media/portal-images/Portal-Jobs.jpg\",\"^7\",\"Jobs Diagnostics\"]]],\"11\",[\"^ \",\"^7\",\"Poverty\",\"^5M\",[[\"^ \",\"^5N\",\"The <a href='https://pip.worldbank.org/'>Poverty and Inequality Platform</a> website allows you to explore data and indicators based on different poverty lines.\",\"^5O\",\"https://pip.worldbank.org/\",\"img\",\"/media/portal-images/Portal-Poverty-Equity-Data.jpg\",\"^7\",\"Poverty and Inequality Platform\"]]],\"12\",[\"^ \",\"^7\",\"Private Sector\",\"^5M\",[[\"^ \",\"^5N\",\"The <a href='http://www.doingbusiness.org'>Doing Business project</a> provides objective measures of business regulations for local firms in 189 economies and selected cities at the subnational level.\",\"^5O\",\"http://www.doingbusiness.org/\",\"img\",\"/media/portal-images/Portal-Doing-Business.jpg\",\"^7\",\"Doing Business\"],[\"^ \",\"^5N\",\"<a href='http://www.enterprisesurveys.org/'>Enterprise Surveys</a> provide the world\\\"s most comprehensive company-level data in emerging markets and developing economies. Business data are available on 130,000 firms in 135 countries.\",\"^5O\",\"http://www.enterprisesurveys.org/\",\"img\",\"/media/portal-images/Portal-Enterprise-Surveys.jpg\",\"^7\",\"Enterprise Surveys\"],[\"^ \",\"^5N\",\"The <a href='http://datatopics.worldbank.org/consumption/'>Global Consumption Database</a> is a one-stop source of data on household consumption patterns in developing countries. It is designed to serve a wide range of users - from researchers seeking data for analytical studies to businesses seeking a better understanding of the markets into which they are expanding or those they are already serving.\",\"^5O\",\"http://datatopics.worldbank.org/consumption/\",\"img\",\"/media/portal-images/Portal-Global-Consumption-Database.jpg\",\"^7\",\"Household Consumption Data and Statistics\"]]],\"13\",[\"^ \",\"^7\",\"Public Sector\",\"^5M\",[[\"^ \",\"^5N\",\"The World Bank’s <a href='http://datatopics.worldbank.org/statisticalcapacity'>Statistical Capacity Indicator</a> is a composite score assessing the capacity of a country\\\"s statistical system. It is based on a diagnostic framework consisting of three assessment areas: methodology; data sources; and periodicity and timeliness.\",\"^5O\",\"http://datatopics.worldbank.org/statisticalcapacity\",\"img\",\"/media/portal-images/Portal-Data-on-Statistical-Capacity.jpg\",\"^7\",\"Data on Statistical Capacity\"],[\"^ \",\"^5N\",\"The <a href='http://datatopics.worldbank.org/cpia'>Country Policy &amp; Institution Assessment</a> (CPIA) is a diagnostic tool that is intended to capture the quality of a country\\\"s policies and institutional arrangements.\",\"^5O\",\"http://datatopics.worldbank.org/cpia\",\"img\",\"/media/portal-images/Portal-CPIA.jpg\",\"^7\",\"Country Policy & Institutional Assessments\"]]],\"17\",[\"^ \",\"^7\",\"Gender\",\"^5M\",[[\"^ \",\"^5N\",\"The <a href='http://datatopics.worldbank.org/gender'>Gender Data Portal</a> is a one-stop source of information on gender at the country level—a compilation of data on key gender topics from national statistics agencies, United Nations databases, and World Bank-conducted or funded surveys.\",\"^5O\",\"http://datatopics.worldbank.org/gender\",\"img\",\"/media/portal-images/Portal-GenderStats.png\",\"^7\",\"Gender Equality Data & Statistics\"]]],\"19\",[\"^ \",\"^7\",\"Climate Change\",\"^5M\",[[\"^ \",\"^5N\",\"The <a href='https:climateknowledgeportal.worldbank.org'>Climate Change Knowledge Portal</a> (CCKP) provides climate data and climate-risk information for users to understand and communicate future climate change scenarios.\",\"^5O\",\"http://climateknowledgeportal.worldbank.org\",\"img\",\"/media/portal-images/portal-climate-change-2021.jpeg\",\"^7\",\"Climate Change Knowledge Portal\"],[\"^ \",\"^5N\",\"The <a href='http://carbonpricingdashboard.worldbank.org'>Carbon Pricing Dashboard</a> provides up-to-date information on existing and emerging carbon pricing initiatives around the world.\",\"^5O\",\"http://carbonpricingdashboard.worldbank.org\",\"img\",\"/media/portal-images/carbonpricingdashboard.png\",\"^7\",\"Carbon Pricing Dashboard\"]]],\"20\",[\"^ \",\"^7\",\"External Debt\",\"^5M\",[[\"^ \",\"^5N\",\"The <a href='http://datatopics.worldbank.org/debt'>Debt Data portal</a> serves as a central hub for information and access to debt statistics.\",\"^5O\",\"http://datatopics.worldbank.org/debt\",\"img\",\"/media/portal-images/Portal-Global-Debt-Data.jpg\",\"^7\",\"Debt Data\"]]],\"21\",[\"^ \",\"^7\",\"Trade\",\"^5M\",[[\"^ \",\"^5N\",\"The <a href='http://wits.worldbank.org'>World Integrated Trade Solution (WITS)</a> tool accesses and retrieves information on trade and tariffs which is compiled by several international organizations, including the World Bank. WITS allows you to quickly obtain summary trade and tariff related information without having to execute queries.\",\"^5O\",\"http://wits.worldbank.org/\",\"img\",\"/media/portal-images/Portal-WITS.jpg\",\"^7\",\"WITS: World Integrated Trade Solution\"],[\"^ \",\"^5N\",\"<a href='http://tcdata360.worldbank.org'>TCdata360</a> aggregates 2000+ trade and competitiveness related indicators from 25+ sources inside and outside WBG and presents them in interactive, visual fashion. Users can compare countries over time, download data, create data visualization, read data stories, see data on maps, print reports, copy charts, connect through an API, and more.\",\"^5O\",\"http://tcdata360.worldbank.org\",\"img\",\"/media/portal-images/Portal-TCData360.png\",\"^7\",\"TCdata36